（世界引擎已就绪 · 渲染版）

欢迎。这是带【交互面板】的世界模拟器：上方是实时世界状态 HUD，下方是修改器指令栏——点选指令、填内容、发送即可修改世界，全程不用手打指令前缀。

在你喊出「开始」之前，我们先完成初始化。请按以下清单告诉我设定（可逐项回复或一次性填充，留空的我自动补全）：

【1. 世界观】世界类型（科幻/奇幻/现代/末世/架空…）、时代风格、舞台规模
【2. 世界规则】有无超自然力量、科技水平、世界基调
【3. 背景与势力】生物/种族/势力/格局
【4. 初始人物】姓名、身份、外貌、能力与局限、目的、起点状态
【5. 时间起点】从哪个时刻/场景切入

填得差不多，对我说「开始」——世界即固化并开始运转。

💡 世界内任何时候说「开启修改器模式」打开修改器，然后直接用下方指令栏改世界；不带指令的发言照常游玩。



```html
<html><head><meta charset="utf-8"><style>
  :root{
    --bg:#0d1117aa; --panel:#161b22ee; --line:#30363d; --txt:#e6edf3;
    --acc:#58a6ff; --acc2:#3fb950; --warn:#d29922;
    --mono:ui-monospace,SFMono-Regular,Menlo,monospace;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  body{background:transparent;color:var(--txt);font-family:var(--mono);font-size:13px;padding:8px}
  .wrap{display:flex;flex-direction:column;gap:8px;max-width:620px}
  /* ===== HUD ===== */
  .hud{background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:10px 12px;backdrop-filter:blur(4px)}
  .hud-title{font-size:11px;letter-spacing:2px;color:var(--acc);font-weight:700;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center}
  .hud-title .mode{color:var(--warn);letter-spacing:0;text-transform:uppercase}
  .hud-grid{display:grid;grid-template-columns:60px 1fr 60px 1fr;gap:3px 10px}
  .hud-grid .k{color:#8b949e;font-size:11px}
  .hud-grid .v{font-size:12px}
  .hud-grid .v.full{grid-column:span 3;min-height:14px}
  .hud-empty{color:#484f58;font-size:11px;margin-top:4px}
  /* ===== CMD BAR ===== */
  .cmd{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px}
  .cmd-title{font-size:11px;letter-spacing:2px;color:var(--acc2);font-weight:700;margin-bottom:8px}
  .row{display:flex;gap:8px;align-items:center;margin-bottom:6px}
  .row label{font-size:11px;color:#8b949e;width:36px;flex:none}
  select,.inp{background:#0d1117;border:1px solid var(--line);color:var(--txt);border-radius:6px;padding:6px 8px;font-family:var(--mono);font-size:12px;flex:1}
  select:focus,.inp:focus{outline:none;border-color:var(--acc)}
  .inp::placeholder{color:#484f58}
  .btnrow{display:flex;gap:8px;margin-top:4px}
  .btn{flex:1;background:var(--acc);color:#0d1117;border:none;border-radius:6px;padding:7px;font-weight:700;font-family:var(--mono);font-size:12px;cursor:pointer;transition:.15s}
  .btn:hover{filter:brightness(1.15);transform:translateY(-1px)}
  .btn:active{transform:translateY(0)}
  .btn.send{background:var(--acc2)}
  .preview-line{background:#161b22;border:1px dashed var(--line);border-radius:6px;padding:6px 8px;font-size:11px;color:#8b949e;margin-top:6px;min-height:16px;word-break:break-all}
  .toast{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);background:var(--acc2);color:#0d1117;padding:6px 12px;border-radius:20px;font-size:12px;font-weight:700;opacity:0;transition:.25s;pointer-events:none;z-index:999}
  .toast.show{opacity:1}
  .toast.err{background:#f85149}
</style></head><body>
<div class="wrap">
  <!-- ========== HUD（字段由模型每轮填充，占位符 __XXX__ 生成时替换）========== -->
  <div class="hud">
    <div class="hud-title"><span>🌍 世界状态</span><span class="mode" id="hud-mode">模式__MODE__</span></div>
    <div class="hud-grid">
      <div class="k">场景</div><div class="v full">__SCENE__</div>
      <div class="k">时间</div><div class="v">__TIME__</div>
      <div class="k">天气</div><div class="v">__WEATHER__</div>
      <div class="k">地点</div><div class="v">__LOC__</div>
      <div class="k">主角</div><div class="v">__CHAR__</div>
      <div class="k">事件</div><div class="v full">__EVENT__</div>
    </div>
  </div>
  <!-- ========== CMD BAR ========== -->
  <div class="cmd">
    <div class="cmd-title">⚙️ 修改器指令</div>
    <div class="row">
      <label>指令</label>
      <select id="sel-cmd"></select>
    </div>
    <div class="row">
      <label>内容</label>
      <input class="inp" id="inp-content" placeholder="输入想改的内容，如：改成阴天" autocomplete="off">
    </div>
    <div class="btnrow">
      <button class="btn send" id="btn-send">✔ 发送修改指令</button>
    </div>
    <div class="preview-line" id="preview">（发送预览）</div>
  </div>
</div>
<div class="toast" id="toast"></div>

<script>
(() => {
  'use strict';
  // ===== 26 条指令数据 =====
  const CMDS = [
    {g:'世界·设定',list:[
      {k:'&设定',t:'设定',e:'改世界规则/物理常数/大局。例：重力减半'},
      {k:'&地图',t:'地图',e:'改地理/地点/地貌。例：城镇以北升起雪山'},
      {k:'&时间',t:'时间',e:'快进/拨回/暂停时间。例：快进到三个月后'},
      {k:'&历史',t:'历史',e:'改写过往历史。例：十年前爆发过瘟疫'},
      {k:'&势力',t:'势力',e:'改/建/灭势力国家。例：龙鳞王国向边境宣战'}]},
    {g:'事件·天象',list:[
      {k:'&事件',t:'事件',e:'强制触发事件。例：三天后王都陷落'},
      {k:'&天气',t:'天气',e:'强设天气天象。例：今夜流星火雨'},
      {k:'&天启',t:'天启',e:'世界级神迹灾难。例：陨石砸向大陆中心'}]},
    {g:'人物·玩家',list:[
      {k:'&记忆',t:'记忆',e:'改写记忆认知。例：让凯忘记见过我'},
      {k:'&传送',t:'传送',e:'移动玩家到任意地点/时间。例：到王都皇宫大殿'},
      {k:'&注入',t:'注入',e:'加人物/物品/能力。例：主角获得龙之力'},
      {k:'&伪装',t:'伪装',e:'变外貌/身份/气息。例：我变成镇长模样'},
      {k:'&气质',t:'气质',e:'加气场氛围光环。例：周身危险气息'},
      {k:'&心灵',t:'心灵',e:'植入潜意识暗示。例：让猎人觉得今晚不该进山'},
      {k:'&角色',t:'角色',e:'改玩家属性/财富。例：钱袋多出五百金币'},
      {k:'&NPC',t:'NPC',e:'强制NPC行动/态度。例：铁匠今晚跟踪我'},
      {k:'&关系',t:'关系',e:'建/改人际关系。例：镇长是故交'},
      {k:'&改写',t:'改写',e:'改写已有设定/人物/事件。例：领主换财迷胖子'},
      {k:'&删除',t:'删除',e:'移除世界对象。例：删除城镇领主'}]},
    {g:'剧情·叙事',list:[
      {k:'&剧情',t:'剧情',e:'强推/跳转剧情。例：明天夜里主角被刺杀'},
      {k:'&对话',t:'对话',e:'强插/改写对话。例：铁匠喊住我别走货'},
      {k:'&视角',t:'视角',e:'切/展示远处视角。例：展示王都此刻'},
      {k:'&刷新',t:'刷新',e:'重生成场景细节/NPC。例：猎人换成别人'}]},
    {g:'查询·万能',list:[
      {k:'&日志',t:'日志',e:'回溯过去时间线（查询）。例：过去三天发生了什么'},
      {k:'&状态',t:'状态',e:'查看世界全貌（查询）。例：当前城镇'},
      {k:'&Any',t:'Any(万能)',e:'兜底任意未覆盖修改。例：让全世界说反话'}]},
  ];

  // ===== 指令下拉 =====
  const sel = document.getElementById('sel-cmd');
  CMDS.forEach(g=>{
    const og=document.createElement('optgroup'); og.label=g.g;
    g.list.forEach(c=>{
      const o=document.createElement('option');
      o.value=c.k; o.text=`${c.k} ${c.t}`; o.title=c.e; og.appendChild(o);
    });
    sel.appendChild(og);
  });

  // ===== 预览 + 发送 =====
  const inp=document.getElementById('inp-content');
  const preview=document.getElementById('preview');
  const btn=document.getElementById('btn-send');
  const modeEl=document.getElementById('hud-mode');

  // ===== 模式判定：仅模式C（修改器）允许发送修改指令 =====
  // 当前模式从 HUD 的模式字段解析（模型每轮填入 __MODE__，形如 模式A/模式B/模式C）
  function currentMode(){
    if(!modeEl) return null;
    const t=(modeEl.textContent||'').trim();
    const m=t.match(/[ABCabC]/);
    return m ? m[0].toUpperCase() : null;
  }
  function canModify(){
    const m=currentMode();
    return m==='C';
  }
  function refreshModeState(){
    const ok=canModify();
    if(btn){
      btn.disabled=!ok;
      btn.style.opacity= ok? '1':'0.45';
      btn.style.cursor= ok? 'pointer':'not-allowed';
    }
    if(inp){
      inp.disabled=!ok;
      inp.style.opacity= ok? '1':'0.55';
    }
    if(preview){
      preview.textContent = ok
        ? (inp.value.trim() ? cur()+' '+inp.value.trim() : (cur()||'（先选指令再输入内容）'))
        : '⚠️ 当前模式'+ (currentMode()||'?') +'：需先「开启修改器模式」(模式C) 才能使用修改指令';
    }
  }
  function cur(){ return sel.value||'&Any'; }
  function renderPrev(){
    const v=inp.value.trim();
    preview.textContent = v ? `${cur()} ${v}` : (cur()?cur():'（先选指令再输入内容）');
  }
  // 监控模式变化：用 MutationObserver 盯 hud-mode 文本变化，切换即刷新按钮态
  if(modeEl && window.MutationObserver){
    try{
      new MutationObserver(()=>{ refreshModeState(); })
        .observe(modeEl, { childList:true, subtree:true, characterData:true });
    }catch(e){}
  }
  inp.addEventListener('input', ()=>{ if(canModify()) renderPrev(); });
  sel.addEventListener('change', ()=>{ if(canModify()) renderPrev(); });
  refreshModeState();

  window.sendModCmd = async function(){
    // 模式拦截（双重保险）：仅模式C允许发送修改指令
    if(!canModify()){ toast('需先「开启修改器模式」(模式C) 才能使用修改指令', true); return; }
    const v=inp.value.trim();
    if(!v){ toast('请先输入要修改的内容',true); return; }
    const full=`${cur()} ${v}`;
    try{
      const TH = window.TavernHelper || (window.parent && window.parent.TavernHelper);
      if(TH && typeof TH.generate==='function' && typeof TH.createChatMessages==='function'){
        // 1) 触发模型生成（user_input 作为本次输入，但不会写进聊天界面）
        const result = await TH.generate({ user_input: full });
        // 2) 提取 AI 回复文本
        let replyText = '';
        if(typeof result === 'string') replyText = result;
        else if(result && typeof result.text === 'string') replyText = result.text;
        else if(result && typeof result.message === 'string') replyText = result.message;
        else if(result && result.content) replyText = String(result.content);
        // 3) 把【用户指令 + AI 回复】两条一起写回聊天界面
        const msgs = [{ role: 'user', message: full }];
        if(replyText) msgs.push({ role: 'assistant', message: replyText });
        await TH.createChatMessages(msgs);
        toast(replyText ? '已发送修改指令' : '已发送（无生成回复）');
      } else if(TH && typeof TH.createChatMessages==='function'){
        await TH.createChatMessages([{role:'user', message: full}]);
        toast('已发送：'+full);
      } else {
        toast('未检测到酒馆助手，请安装 JS-Slash-Runner', true);
      }
      inp.value=''; renderPrev();
    }catch(e){ console.error(e); toast('发送失败：'+((e&&e.message)||e), true); }
  };
  btn.addEventListener('click', window.sendModCmd);
  inp.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); window.sendModCmd(); } });

  function toast(msg,err){
    const t=document.getElementById('toast');
    t.textContent=msg; t.className='toast show'+(err?' err':'');
    setTimeout(()=>{ t.className='toast'; }, 2200);
  }
  renderPrev();
})();
</script>
</body></html>

```
